import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { requireRoomPermission } from "@/lib/audio-room-management";
export function OPTIONS(){return mobileOptions()}
export async function POST(request,{params}){try{const actor=await requireMobileUser(request),{roomId}=await params,body=await request.json();const room=await prisma.audioRoom.findUnique({where:{roomId:decodeURIComponent(roomId)},select:{id:true,roomId:true,ownerId:true}});if(!room)throw new Error("ROOM_UNAVAILABLE");await requireRoomPermission(room,actor.id,"canModerateMembers");const target=await prisma.user.findUnique({where:{publicId:String(body.publicId??"")},select:{id:true,publicId:true}});if(!target)throw new Error("USER_NOT_FOUND");if(target.id===room.ownerId)throw Object.assign(new Error("The room owner cannot be removed."),{code:"VALIDATION_ERROR"});const banRequested=body.banMinutes!==null&&body.banMinutes!==undefined,minutes=banRequested?Number(body.banMinutes):null;if(banRequested&&(!Number.isSafeInteger(minutes)||minutes<0||minutes>525600))throw Object.assign(new Error("banMinutes must be null or 0 to 525600."),{code:"VALIDATION_ERROR"});const reason=String(body.reason??"").trim().slice(0,300)||null,expiresAt=banRequested&&minutes>0?new Date(Date.now()+minutes*60000):null;const updated=await prisma.$transaction(async tx=>{if(banRequested){await tx.audioRoomBan.updateMany({where:{audioRoomId:room.id,userId:target.id,revokedAt:null},data:{revokedAt:new Date()}});await tx.audioRoomBan.create({data:{publicId:`RBAN-${crypto.randomUUID()}`,audioRoomId:room.id,userId:target.id,actorId:actor.id,reason,expiresAt}})}await tx.audioRoomMember.updateMany({where:{audioRoomId:room.id,userId:target.id},data:{socketCount:0,lastSeenAt:new Date(),isDeafened:false,deafenedUntil:null}});await tx.audioRoomSeat.updateMany({where:{audioRoomId:room.id,occupantUserId:target.id},data:{occupantUserId:null,occupiedAt:null,isMuted:true,isForceMuted:false,forceMutedUntil:null,isSpeaking:false}});await tx.audioRoomModerationLog.create({data:{id:`MOD-${crypto.randomUUID()}`,audioRoomId:room.id,actorId:actor.id,targetId:target.id,action:banRequested?"ROOM_BANNED":"KICK",reason,durationMinutes:minutes,expiresAt}});return tx.audioRoom.update({where:{id:room.id},data:{revision:{increment:1}},select:{revision:true}})});globalThis.portalRemoveFromAudioRoom?.(target.publicId,room.roomId,{code:banRequested?"ROOM_BANNED":"ROOM_KICKED",message:"You were removed from this room.",details:{reason,expiresAt:expiresAt?.toISOString()??null}});return mobileJson({success:true,data:{roomId:room.roomId,userId:target.publicId,banExpiresAt:expiresAt?.toISOString()??null,revision:updated.revision}})}catch(e){return mobileApiError(e,"ROOM_KICK_FAILED")}}
